struct DedupConsec<I: Iterator> {
    inner: std::iter::Peekable<I>,
}

impl<I> Iterator for DedupConsec<I>
where I: Iterator, I::Item: PartialEq + Clone {
    type Item = I::Item;
    fn next(&mut self) -> Option<I::Item> {
        let val = self.inner.next()?;
        while self.inner.peek() == Some(&val) { self.inner.next(); }
        Some(val)
    }
}

