use std::time::Duration;
use tokio::time::timeout;

async fn fetch_with_retry(url: &str, retries: u32) -> Result<String, String> {
    for attempt in 0..=retries {
        match timeout(Duration::from_secs(5), reqwest::get(url)).await {
            Ok(Ok(resp)) => return resp.text().await.map_err(|e| e.to_string()),
            _ if attempt < retries => {
                tokio::time::sleep(Duration::from_millis(200 * (attempt as u64 + 1))).await;
            }
            _ => return Err("all retries exhausted".into()),
        }
    }
    unreachable!()
}

