fn remove_negatives(v: &mut Vec<i32>) {
    let indices: Vec<usize> = v.iter().enumerate()
        .filter(|(_, &x)| x < 0)
        .map(|(i, _)| i)
        .collect();
    for i in indices.into_iter().rev() {
        v.remove(i);
    }
}
